EVOLVE: CAP-CREDIT-001_L3_M05_EVOLVE_Step-Up_Reviewer_Exception_Handoff_FINAL_QA_CLEANED_SME_PENDING.xlsx", "EXPRESS: CAP-CREDIT-001_L3_M06_EXPRESS_Final_L3_Exception_Case_Portfolio_FINAL_QA_CLEANED_SME_PENDING.xlsx", "EVOLVE: CAP-CREDIT-001_L3_M06_EVOLVE_Independent_Exception_Transfer_Defence_Pack_FINAL_QA_CLEANED_SME_PENDING.xlsx"]'::jsonb, '{"title": "Analytical Credit Exception Assessment", "description": "Exception-heavy credit files contain conflicting evidence, linked-party/exposure signals and unclear ownership that require analytical support without crossing into credit judgement or fraud conclusions."}'::jsonb, 72, 'intermediate'::public.difficulty_level, 'published'::public.status, 1, TRUE, DEFAULT)
