001_L5_M05_EXPRESS_Credit_Support_Governance_Summary_and_Handoff_Pack_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx", "EVOLVE: CAP-CREDIT-001_L5_M05_EVOLVE_Step-Up_Governance_Handoff_Pack_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx", "EXPRESS: CAP-CREDIT-001_L5_M06_EXPRESS_Final_L5_Workflow_Governance_Portfolio_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx", "EVOLVE: CAP-CREDIT-001_L5_M06_EVOLVE_Independent_Workflow_Governance_Transfer_Defence_Pack_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx"]'::jsonb, '{"title": "Supervised Credit Support Workflow Governance", "description": "A live support queue has ageing cases, recurring evidence defects and junior handoff issues that require supervised governance, coaching and improvement proposals while policy, audit, control and credit authority remain with authorised owners."}'::jsonb, 72, 'expert'::public.difficulty_level, 'published'::public.status, 1, TRUE, DEFAULT)
